// Songbook clipper for the iOS Shortcuts action "Run JavaScript on Web Page".
//
// Generated by scripts/build-shortcut.js from:
//   extension/chord-utils-content.js
//   extension/guitartuna-content.js
//   extension/ultimate-guitar-content.js
//   extension/clipper-content.js
//   extension/shortcut-entry.js
//
// Do not edit this file. Edit the sources and run `npm run build:shortcut`.

(() => {
  const CHORD_TOKEN_PATTERN = /^[A-G](?:#|b)?(?:(?:[Mm]aj|[Mm]in|[Dd]im|[Aa]ug|[Ss]us|[Aa]dd|[Nn]o|m|M)?[0-9#b+\-()]*)*(?:\/[A-G](?:#|b)?)?$/;

  function isPlainChordLine(line) {
    const tokens = String(line).trim().split(/\s+/).filter(Boolean);
    if (!tokens.length) return false;

    const musicalTokens = tokens.filter((token) => !isBarToken(token) && !isChordLineDecoration(token));
    if (!musicalTokens.length) return false;

    const chordTokens = musicalTokens.filter(isChordToken);
    return chordTokens.length === musicalTokens.length && (chordTokens.length > 1 || line.trim().length <= 8);
  }

  function isChordToken(token) {
    const normalized = String(token)
      .replace(/^[([{]+/g, "")
      .replace(/[)\]}]+$/g, "")
      .replace(/[.,;:]+$/g, "");
    return CHORD_TOKEN_PATTERN.test(normalized);
  }

  function isChordLineDecoration(token) {
    return /^[^A-Za-z0-9]+$/.test(token);
  }

  function isBarToken(token) {
    return /^[|:]+$/.test(token) || /^\(?x\d+\)?$/i.test(token) || /^\(?\d+x\)?$/i.test(token) || /^N\.?C\.?$/i.test(token);
  }

  globalThis.songbookChordUtils = { isPlainChordLine, isChordToken };
})();

(() => {
  // GuitarTuna lays a song out as a beat grid: every lyric line is a row of beat
  // cells, each carrying a `--w` custom property for the number of lyric
  // characters it spans, and a chord hangs off the cell it starts on. Adding up
  // the widths of the cells before a chord gives the text column that chord sits
  // above, which is all a plain chords-over-lyrics sheet needs.
  function buildChordSheet(blocks) {
    const lines = [];

    for (const block of blocks || []) {
      if (block.type === "section") {
        if (lines.length && lines[lines.length - 1] !== "") lines.push("");
        if (block.label) lines.push(`[${block.label}]`);
        continue;
      }

      const chordLine = buildChordLine(block.chords);
      const lyric = String(block.lyric || "").replace(/\s+$/, "");

      if (chordLine) lines.push(chordLine);
      if (lyric) lines.push(lyric);
      if (!chordLine && !lyric && lines.length && lines[lines.length - 1] !== "") lines.push("");
    }

    // Trimming whitespace here would eat the indent of a sheet whose first chord
    // lands mid-line, so only blank lines are dropped from the ends.
    while (lines.length && !lines[0].trim()) lines.shift();
    while (lines.length && !lines[lines.length - 1].trim()) lines.pop();

    return lines.join("\n");
  }

  function buildChordLine(chords) {
    let line = "";

    for (const entry of chords || []) {
      const chord = String(entry?.chord || "").trim();
      if (!chord) continue;

      // Two chords on the same beat still need a gap between them.
      const start = Math.max(Number(entry.column) || 0, line ? line.length + 1 : 0);
      line = line.padEnd(start, " ") + chord;
    }

    return line;
  }

  function readBlocks(root) {
    return [...root.querySelectorAll(".partContainer, .line")].map((node) => (
      node.classList.contains("partContainer")
        ? { type: "section", label: (node.querySelector(".part_type")?.textContent || "").trim() }
        : { type: "line", lyric: readLyric(node), chords: readChords(node) }
    ));
  }

  function readChords(line) {
    const chords = [];
    let column = 0;

    for (const beat of line.querySelectorAll(".beat_info")) {
      const chordElement = beat.querySelector("[data-chord]");
      const chord = (chordElement?.getAttribute("data-chord") || chordElement?.textContent || "").trim();
      if (chord) chords.push({ column, chord });
      column += Number(beat.style.getPropertyValue("--w")) || 0;
    }

    return chords;
  }

  function readLyric(line) {
    return [...line.children]
      .filter((child) => child.tagName === "DIV" && !child.classList.contains("beat_info"))
      .map((child) => child.textContent || "")
      .join("");
  }

  function findSheetRoot(doc) {
    return doc.querySelector('#songcontent, [data-testid="song-lyrics"], .lyrics-root');
  }

  function extractSong(doc) {
    const root = findSheetRoot(doc);
    if (!root) throw new Error("No GuitarTuna chord sheet was found on this page.");

    const rawContent = buildChordSheet(readBlocks(root));
    if (!rawContent) throw new Error("The GuitarTuna chord sheet on this page is empty.");

    const meta = readMeta(doc);

    return {
      title: meta.title || "Untitled song",
      artist: meta.artist || "Unknown artist",
      key: meta.key,
      capo: meta.capo,
      tuning: meta.tuning,
      tags: ["clipped", "guitartuna"],
      sourceUrl: doc.location?.href || "",
      rawContent
    };
  }

  // GuitarTuna publishes the song details as schema.org MusicComposition, with
  // tuning, capo and tempo packed into one `text` string.
  function readMeta(doc) {
    const meta = { title: "", artist: "", key: "", capo: "", tuning: "" };

    for (const script of doc.querySelectorAll('script[type="application/ld+json"]')) {
      let parsed = null;
      try {
        parsed = JSON.parse(script.textContent || "");
      } catch {
        continue;
      }
      if (!parsed || typeof parsed !== "object") continue;
      if (![parsed["@type"]].flat().includes("MusicComposition")) continue;

      meta.title = meta.title || stripFormatSuffix(parsed.name);
      meta.artist = meta.artist || String([parsed.composer].flat()[0]?.name || "").trim();
      meta.key = meta.key || normalizeKey(parsed.musicalKey);

      const text = String(parsed.text || "");
      meta.tuning = meta.tuning || (text.match(/Tuning:\s*(.+?)(?=\s+(?:Key|Capo|Tempo):|$)/i)?.[1] || "").trim();
      // GuitarTuna currently publishes "Capo: fret 3" while older pages used
      // "Capo: 3". Accept both forms.
      meta.capo = meta.capo || (text.match(/Capo:\s*(?:fret\s*)?(\d+)/i)?.[1] || "");
    }

    // e.g. "LITTLE MUSGRAVE chords by James Yorkston, The Big Eyes Family Players"
    const heading = (doc.querySelector("h1")?.textContent || "").trim().replace(/\s+/g, " ");
    const headingMatch = heading.match(/^(.*?)\s+(?:(?:easy|simplified)\s+(?:guitar\s+)?)?(?:chords|tabs?)\s+by\s+(.*)$/i);
    if (headingMatch) {
      meta.title = meta.title || headingMatch[1].trim();
      meta.artist = meta.artist || headingMatch[2].trim();
    }

    return meta;
  }

  function stripFormatSuffix(value) {
    return String(value || "").replace(/\s*\((?:chords|tabs?)\)\s*$/i, "").trim();
  }

  // "A minor" reads as a sentence next to the "Am" and "Db" keys other sources give.
  function normalizeKey(value) {
    const text = String(value || "").trim();
    const match = text.match(/^([A-G][#b]?)\s*(minor|major|min|maj|m)?$/i);
    if (!match) return text;
    const quality = match[2] || "";
    return /^m/i.test(quality) && !/^maj/i.test(quality) ? `${match[1]}m` : match[1];
  }

  globalThis.songbookGuitarTuna = { buildChordSheet, readBlocks, extractSong };
})();

(() => {
  // Ultimate Guitar ships the tab as JSON inside the server HTML and renders it
  // with React. Everything here works from a passed-in document so the same
  // reader serves the extension, the iPhone Shortcut and the tests.
  async function extractSong(doc = document) {
    if (!globalThis.songbookChordUtils?.isPlainChordLine) {
      throw new Error("Songbook chord parser did not load.");
    }

    const pageUrl = doc.location?.href || "";
    let pageData = extractUltimateGuitarData(doc);

    // Ultimate Guitar's React app deletes the js-store payload from the DOM once it
    // hydrates, so a page the user has been reading no longer carries it. Re-reading
    // the server HTML recovers the original tab data, including the [ch] chord markup.
    if (!hasUsableTabData(pageData)) {
      const serverDocument = await fetchServerDocument(pageUrl);
      if (serverDocument) pageData = extractUltimateGuitarData(serverDocument);
    }

    const tabView = findTabView(pageData);
    const tabInfo = findTabInfo(pageData);
    const meta = tabView?.meta || {};
    const jsonLd = extractJsonLdMeta(doc);
    const content = getNested(tabView, ["wiki_tab", "content"]) || getNested(tabView, ["tab", "content"]) || findChordContent(pageData);
    const rawContent = normalizeContent(content || extractVisibleTabText(doc));

    if (!rawContent) {
      throw new Error("No chord sheet text was found on the loaded page.");
    }

    return {
      title: tabInfo?.song_name || tabView?.song_name || tabView?.name || jsonLd.title || inferTitle(doc) || "Untitled song",
      artist: tabInfo?.artist_name || tabView?.artist_name || tabView?.artist?.name || jsonLd.artist || inferArtist(doc) || "Unknown artist",
      key: meta.tonality || tabInfo?.tonality_name || tabView?.tonality_name || jsonLd.key || "",
      capo: normalizeCapo(meta.capo ?? tabView?.capo ?? jsonLd.capo),
      tuning: meta.tuning?.name || meta.tuning?.value || tabView?.tuning?.name || tabView?.tuning_name || jsonLd.tuning || "",
      tags: ["clipped", "ultimate-guitar"],
      sourceUrl: pageUrl,
      rawContent
    };
  }

  function hasUsableTabData(pageData) {
    const tabView = findTabView(pageData);
    return Boolean(getNested(tabView, ["wiki_tab", "content"]) || getNested(tabView, ["tab", "content"]) || findChordContent(pageData));
  }

  async function fetchServerDocument(pageUrl) {
    try {
      const response = await fetch(pageUrl, { credentials: "include" });
      if (!response.ok) return null;
      return new DOMParser().parseFromString(await response.text(), "text/html");
    } catch {
      return null;
    }
  }

  function extractUltimateGuitarData(doc) {
    const candidates = [];

    doc.querySelectorAll(".js-store[data-content], [data-content]").forEach((element) => {
      const value = element.getAttribute("data-content");
      if (value && hasTabDataMarker(value)) candidates.push(decodeHtml(doc, value));
    });

    doc.querySelectorAll("script").forEach((script) => {
      const text = script.textContent || "";
      if (!hasTabDataMarker(text)) return;

      const initialState = text.match(/window\.__INITIAL_STATE__\s*=\s*({[\s\S]*?});/);
      if (initialState) candidates.push(initialState[1]);

      const pageStore = text.match(/window\.UGAPP\.store\.page\s*=\s*({[\s\S]*?});/);
      if (pageStore) candidates.push(pageStore[1]);

      const markerIndex = text.indexOf('"tab_view"');
      const surrounding = markerIndex >= 0 ? extractSurroundingJsonObject(text, markerIndex) : null;
      if (surrounding) candidates.push(surrounding);
    });

    for (const candidate of candidates) {
      const parsed = tryParseJson(doc, candidate);
      if (parsed && (findTabView(parsed) || findChordContent(parsed))) return parsed;
    }

    return {};
  }

  function hasTabDataMarker(value) {
    const text = String(value || "");
    const hasKnownUgKey = /tab_view|wiki_tab|song_name|artist_name|tonality_name|tab_url|tabContent|wikiTab/i.test(text);
    const hasGenericContent = /"content"\s*:|&quot;content&quot;\s*:|data-content=/i.test(text);
    const hasMusicContext = /chords|ultimate-guitar|tabs|capo|\[ch\]|\\n\s*[A-G](?:#|b)?/i.test(text);
    return (hasKnownUgKey && /content|chords|tab/i.test(text)) || (hasGenericContent && hasMusicContext);
  }

  function findTabView(value) {
    if (!value || typeof value !== "object") return null;
    if (value.tab_view && typeof value.tab_view === "object") return value.tab_view;

    const stack = [value];
    const seen = new Set();

    while (stack.length) {
      const current = stack.pop();
      if (!current || typeof current !== "object" || seen.has(current)) continue;
      seen.add(current);

      if (current.tab_view && typeof current.tab_view === "object") return current.tab_view;
      if (current.store?.page?.data?.tab_view) return current.store.page.data.tab_view;
      if (current.page?.data?.tab_view) return current.page.data.tab_view;

      Object.values(current).forEach((child) => {
        if (child && typeof child === "object") stack.push(child);
      });
    }

    return null;
  }

  // Song, artist and key moved off tab_view and onto the sibling `tab` record.
  function findTabInfo(value) {
    if (!value || typeof value !== "object") return null;

    const stack = [value];
    const seen = new Set();

    while (stack.length) {
      const current = stack.pop();
      if (!current || typeof current !== "object" || seen.has(current)) continue;
      seen.add(current);

      if (current.tab && typeof current.tab === "object" && current.tab.song_name) return current.tab;

      Object.values(current).forEach((child) => {
        if (child && typeof child === "object") stack.push(child);
      });
    }

    return null;
  }

  // Ultimate Guitar still publishes clean metadata as schema.org JSON-LD, which
  // survives hydration and covers pages where the tab payload cannot be read.
  function extractJsonLdMeta(doc) {
    const meta = { title: "", artist: "", key: "", capo: "", tuning: "" };

    for (const script of doc.querySelectorAll('script[type="application/ld+json"]')) {
      let parsed = null;
      try {
        parsed = JSON.parse(script.textContent || "");
      } catch {
        continue;
      }
      if (!parsed || typeof parsed !== "object") continue;

      const types = [parsed["@type"]].flat();

      if (types.includes("MusicRecording")) {
        meta.title = meta.title || String(parsed.name || "").trim();
        meta.artist = meta.artist || String(parsed.byArtist?.name || "").trim();
      }

      if (types.includes("MusicComposition")) {
        meta.artist = meta.artist || String(parsed.composer?.name || "").trim();
        meta.key = meta.key || String(parsed.musicalKey || "").trim();

        // e.g. "Difficulty: Beginner Tuning: E A D G B E Key: Db Capo: 1st fret"
        const text = String(parsed.text || "");
        meta.tuning = meta.tuning || (text.match(/Tuning:\s*(.+?)\s+Key:/i)?.[1] || "").trim();
        meta.capo = meta.capo || (text.match(/Capo:\s*(\d+)\s*(?:st|nd|rd|th)?\s*fret/i)?.[1] || "").trim();
      }
    }

    return meta;
  }

  function extractVisibleTabText(doc) {
    const selectors = [
      '[data-name="tab-content"]',
      '[data-testid="tab-content"]',
      '[data-content="tab"]',
      ".js-tab-content",
      '[class*="TabContent"]',
      '[class*="tabContent"]',
      '[class*="styles__TabContent"]',
      "pre",
      "article",
      "main"
    ];

    for (const selector of selectors) {
      const element = doc.querySelector(selector);
      const text = element?.innerText?.trim();
      if (text && looksLikeChordSheet(text)) return text;
    }

    const candidates = [...doc.querySelectorAll("div, section")]
      .map((element) => element.innerText?.trim() || "")
      .filter((text, index, list) => text.length > 80 && list.indexOf(text) === index)
      .map((text) => ({ text, score: chordSheetScore(text) }))
      .filter((candidate) => candidate.score >= 8)
      .sort((a, b) => b.score - a.score || a.text.length - b.text.length);

    return candidates[0]?.text || "";
  }

  function looksLikeChordSheet(text) {
    return chordSheetScore(text) >= 8;
  }

  function chordSheetScore(text) {
    const { isPlainChordLine } = globalThis.songbookChordUtils;
    const lines = String(text || "").split("\n").map((line) => line.trimEnd());
    const bracketChordCount = (text.match(/\[ch\][\s\S]*?\[\/ch\]/gi) || []).length;
    const sectionCount = lines.filter((line) => /^\s*\[(?:Intro|Verse|Chorus|Bridge|Outro|Pre-Chorus|Interlude|Solo|Instrumental)[^\]]*\]\s*$/i.test(line)).length;
    const chordLineCount = lines.filter(isPlainChordLine).length;
    const lyricLineCount = lines.filter((line) => /[a-z]{2,}/i.test(line) && !isPlainChordLine(line)).length;

    return bracketChordCount * 6 + sectionCount * 2 + chordLineCount * 4 + Math.min(lyricLineCount, chordLineCount + 3);
  }

  function findChordContent(value) {
    const stack = [value];
    const seen = new Set();
    let best = "";
    let bestScore = 0;

    while (stack.length) {
      const current = stack.pop();
      if (!current || typeof current !== "object" || seen.has(current)) continue;
      seen.add(current);

      for (const [key, child] of Object.entries(current)) {
        if (typeof child === "string" && /content|text|body|tab/i.test(key)) {
          const normalized = normalizeContent(child);
          const score = chordSheetScore(normalized);
          if (score > bestScore) {
            best = normalized;
            bestScore = score;
          }
        } else if (child && typeof child === "object") {
          stack.push(child);
        }
      }
    }

    return bestScore >= 8 ? best : "";
  }

  function normalizeContent(value) {
    return decodeEscapes(String(value || ""))
      .replace(/\r\n?/g, "\n")
      .replace(/\[\/?tab\]/gi, "")
      .trim();
  }

  function extractSurroundingJsonObject(source, markerIndex) {
    let start = markerIndex;
    while (start >= 0 && source[start] !== "{") start -= 1;
    if (start < 0) return null;

    let depth = 0;
    let inString = false;
    let escaped = false;

    for (let index = start; index < source.length; index += 1) {
      const char = source[index];

      if (inString) {
        if (escaped) {
          escaped = false;
        } else if (char === "\\") {
          escaped = true;
        } else if (char === '"') {
          inString = false;
        }
        continue;
      }

      if (char === '"') inString = true;
      if (char === "{") depth += 1;
      if (char === "}") depth -= 1;
      if (depth === 0) return source.slice(start, index + 1);
    }

    return null;
  }

  function tryParseJson(doc, source) {
    const decoded = decodeHtml(doc, source).trim();
    try {
      return JSON.parse(decoded);
    } catch {
      const unescaped = decoded.replace(/\\"/g, '"').replace(/\\\\/g, "\\");
      try {
        return JSON.parse(unescaped);
      } catch {
        return null;
      }
    }
  }

  function inferTitle(doc) {
    return doc.querySelector("h1")?.innerText?.trim() || String(doc.title || "").replace(/\s+chords.*$/i, "").replace(/\s+\|\s+.*$/i, "").trim();
  }

  function inferArtist(doc) {
    const artistLink = doc.querySelector('a[href*="/artist/"], a[href*="/tabs/"]');
    return artistLink?.innerText?.trim() || "";
  }

  function normalizeCapo(value) {
    if (value === undefined || value === null || value === 0 || value === "0") return "";
    return String(value);
  }

  function getNested(source, path) {
    return path.reduce((value, key) => (value && value[key] !== undefined ? value[key] : undefined), source);
  }

  function decodeEscapes(value) {
    const text = String(value);
    if (!/\\(?:n|r|t|"|\\|u[0-9a-f]{4})/i.test(text)) return text;

    try {
      return JSON.parse(`"${text.replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\r/g, "\\r")}"`);
    } catch {
      return text;
    }
  }

  function decodeHtml(doc, value) {
    const textarea = doc.createElement("textarea");
    textarea.innerHTML = String(value);
    return textarea.value;
  }

  globalThis.songbookUltimateGuitar = { extractSong };
})();

(() => {
  // The single entry point both front ends use: the extension injects these
  // readers into the tab and calls this, and the iPhone Shortcut runs the same
  // files as one pasted snippet. Keeping the dispatch here means neither front
  // end carries its own idea of which reader a page needs.
  const READERS = {
    "ultimate-guitar": () => globalThis.songbookUltimateGuitar,
    guitartuna: () => globalThis.songbookGuitarTuna
  };

  const NO_PAGE_MESSAGE = "Open a loaded Ultimate Guitar or GuitarTuna chord page first.";

  async function extractSong(doc = document) {
    const source = detectSource(doc?.location?.href || "");
    if (!source) throw new Error(NO_PAGE_MESSAGE);

    const reader = READERS[source]();
    if (!reader?.extractSong) throw new Error(`Songbook ${source} reader did not load.`);

    return reader.extractSong(doc);
  }

  function detectSource(value) {
    try {
      const { hostname } = new URL(value);
      if (matchesHost(hostname, "ultimate-guitar.com")) return "ultimate-guitar";
      if (matchesHost(hostname, "guitartuna.com")) return "guitartuna";
      return "";
    } catch {
      return "";
    }
  }

  function matchesHost(hostname, domain) {
    const host = hostname.toLowerCase();
    return host === domain || host.endsWith(`.${domain}`);
  }

  globalThis.songbookClipper = { detectSource, extractSong, NO_PAGE_MESSAGE };
})();

(() => {
  // The tail of the built iPhone snippet. iOS has no way to run a Chrome
  // extension, so the Shortcuts action "Run JavaScript on Web Page" plays the
  // part the popup plays on a desktop: it runs the readers above against the
  // Safari page and hands back a Songbook URL for the Shortcut to open. The app
  // decodes the #import= payload on load, saves it and syncs it.
  //
  // Change this to http://127.0.0.1:3000 to clip into a local development copy.
  const SONGBOOK_URL = "https://maxwellriess.github.io/Songbook";

  // Safari carries far longer URLs than this, but a sheet that overruns should
  // say so rather than arrive silently truncated and half-imported.
  const MAX_URL_LENGTH = 60000;

  // Defined by the Shortcuts action. Absent when the extension injects these
  // same files, which is why this tail does nothing there.
  if (typeof completion !== "function") return;

  Promise.resolve()
    .then(() => globalThis.songbookClipper.extractSong(document))
    .then((song) => {
      const url = `${SONGBOOK_URL.replace(/\/+$/, "")}/#import=${encodeBase64Url(JSON.stringify(song))}`;
      if (url.length > MAX_URL_LENGTH) {
        throw new Error("This chord sheet is too long to pass through a URL. Clip it with the browser extension instead.");
      }
      completion({ url, title: song.title || "", artist: song.artist || "" });
    })
    .catch((error) => completion({ error: error?.message || "Clip failed." }));

  // The app decodes with atob over the same base64url alphabet, so the padding
  // and the two substituted characters have to match what it expects.
  function encodeBase64Url(text) {
    const bytes = new TextEncoder().encode(text);
    let binary = "";
    for (const byte of bytes) binary += String.fromCharCode(byte);
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }
})();
